:root {
--radius-none: 0;
--radius-sm: 4px;        /* radius-small — xsmall 버튼·태그 */
--radius-md: 6px;        /* radius-medium1·2 — 기본 버튼(40~48px) */
--radius-lg: 8px;        /* radius-medium3·4 — 큰 버튼·입력창 */
--radius-xl: 12px;       /* radius-xlarge — 카드·모달 (large 10px 도 있음) */
--radius-full: 9999px;   /* radius-max — 단계 표시 원·스위치 */
--shadow-none: none;                                   /* 카드 기본 — 경계선만 */
--shadow-sm: 0 1px 2px rgba(0,0,0,0.05);               /* shadow1 — 입력 hover (추정) */
--shadow-md: 0 2px 8px rgba(0,0,0,0.08);               /* shadow2 — 드롭다운·툴팁 */
--shadow-lg: 0 4px 16px rgba(0,0,0,0.12);              /* shadow3 — 모달 */
--shadow-xl: 0 8px 24px rgba(0,0,0,0.12);              /* 전체 메뉴·바텀시트 (추정) */
--duration-fast: 150ms;                          /* hover 색 변화 (추정) */
--duration-base: 250ms;                          /* 드롭다운·아코디언 (추정) */
--duration-slow: 400ms;                          /* 공식 transition-base, 펼침·전체 메뉴 */
--ease-out: cubic-bezier(0, 0, 0.2, 1);          /* (추정) */
--ease-in-out: ease-in-out;                      /* 공식 */
}
:root {
  /* === 선명한 화면 모드 (KRDS high-contrast) — 검정 바탕, 레이어가 쌓일수록 밝아짐 === */
  /* Primary — 정부 청색. 채움(500)은 기본 모드와 같고, 옅은 면·글자 단계가 뒤집힌다 */
  --color-primary-50:  #020F27;  /* primary-95 — 선택 행·정보 면 */
  --color-primary-100: #03163A;  /* primary-90 — border-primary-light */
  --color-primary-200: #052561;  /* primary-80 */
  --color-primary-300: #083891;  /* primary-70 */
  --color-primary-400: #0B50D0;  /* primary-60 */
  --color-primary-500: #256EF4;  /* primary-50 — 버튼 채움 (모드 공통) */
  --color-primary-600: #86AFF9;  /* primary-30 — 링크 기본·강조 글자 */
  --color-primary-700: #B1CEFB;  /* primary-20 — text-primary */
  --color-primary-800: #D8E5FD;  /* primary-10 */
  --color-primary-900: #ECF2FE;  /* primary-5 */

  /* Secondary — 선명한 화면 모드 전용 청록 계열 */
  --color-secondary-50:  #091F25;  /* secondary-95 — 공식 배너 배경 */
  --color-secondary-500: #268097;  /* secondary-50 */
  --color-secondary-700: #75C0D1;  /* secondary-30 */
  --color-secondary-800: #ABD8E3;  /* secondary-20 — text-secondary */

  /* Point — 정부 적색 (검정 위 글자는 30단계로) */
  --color-point-500: #E0858C;      /* point-30 */

  /* Neutral — 검정에서 흰색으로 반전 */
  --color-neutral-0:    #000000;  /* gray-100 — 페이지 */
  --color-neutral-50:   #131416;  /* gray-95 — surface-gray-subtler */
  --color-neutral-100:  #1E2124;  /* gray-90 — surface-gray-subtle */
  --color-neutral-200:  #33363D;  /* gray-80 — border-gray-light */
  --color-neutral-300:  #464C53;  /* gray-70 — border-gray */
  --color-neutral-500:  #8A949E;  /* gray-40 */
  --color-neutral-700:  #CDD1D5;  /* gray-20 — text-subtle */
  --color-neutral-900:  #F4F5F6;  /* gray-5 — text-basic */
  --color-neutral-1000: #FFFFFF;

  /* Semantic (bg = -95, fg = -20 글자) */
  --color-success-bg: #0E2012;
  --color-success-fg: #A9DAB4;
  --color-warning-bg: #241800;
  --color-warning-fg: #FFC95C;
  --color-error-bg:   #260903;
  --color-error-fg:   #F7AFA1;
  --color-info-bg:    #021A2C;
  --color-info-fg:    #9ED2FA;

  /* Surface — 쌓일수록 밝아진다 */
  --bg-base:     #000000;        /* background-white (HC = gray-100) */
  --bg-subtle:   #131416;        /* surface-gray-subtler */
  --bg-elevated: #1E2124;        /* surface-white-subtler — 카드 */
  --bg-overlay:  rgba(0,0,0,0.75);

  /* Text */
  --text-primary:    #F4F5F6;    /* text-basic (gray-5) */
  --text-secondary:  #CDD1D5;    /* text-subtle (gray-20) */
  --text-tertiary:   #B1B8BE;    /* gray-30 (추정 매핑) */
  --text-on-primary: #FFFFFF;
  --text-disabled:   #58616A;    /* text-disabled (gray-60) */

  /* Border — 선 굵기가 2px 로 두꺼워진다 */
  --border-default: #464C53;     /* border-gray (gray-70) */
  --border-subtle:  #33363D;     /* border-gray-light (gray-80) */
  --border-strong:  #8A949E;     /* border-gray-dark (gray-40) */
  --border-focus:   #256EF4;     /* border-primary */
  --border-width:   2px;         /* border-width-variable-regular (HC) */
}

[data-theme="light"] {
  /* 기본 모드 폴백 */
  --color-primary-50: #ECF2FE; --color-primary-100: #D8E5FD; --color-primary-600: #0B50D0; --color-primary-700: #083891;
  --color-secondary-50: #EEF2F7; --color-point-500: #D63D4A;
  --color-neutral-0: #FFFFFF; --color-neutral-50: #F4F5F6; --color-neutral-100: #E6E8EA; --color-neutral-200: #CDD1D5;
  --color-success-bg: #EAF6EC; --color-success-fg: #267337; --color-warning-bg: #FFF3DB; --color-warning-fg: #8A5C00;
  --color-error-bg: #FDEFEC; --color-error-fg: #BD2C0F; --color-info-bg: #E7F4FE; --color-info-fg: #096AB3;
  --bg-base: #FFFFFF; --bg-subtle: #F4F5F6; --bg-elevated: #FFFFFF; --bg-overlay: rgba(0,0,0,0.5);
  --text-primary: #1E2124; --text-secondary: #464C53; --text-tertiary: #6D7882; --text-disabled: #8A949E;
  --border-default: #B1B8BE; --border-subtle: #CDD1D5; --border-strong: #58616A; --border-width: 1px;
}




.btn {
  font: 700 17px/1.5 "Pretendard GOV", "Pretendard", "Malgun Gothic", sans-serif;
  height: 48px; padding: 0 20px; border-radius: var(--radius-md);
  display: inline-flex; align-items: center; justify-content: center; gap: 4px;
  border: 1px solid transparent; cursor: pointer;
  transition: background-color var(--duration-base) var(--ease-in-out);
}
/* 포커스 = 흰 2px 안쪽 선 + 청색 4px 바깥 고리 (공식 box-shadow-outline) */
.btn:focus-visible { outline: 2px solid #000000; outline-offset: 0; box-shadow: 0 0 0 4px var(--border-focus); }

.btn-primary { background: var(--color-primary-500); color: var(--text-on-primary); }
.btn-primary:hover { background: #0B50D0; }               /* button-primary-fill-hover (primary-60) */
.btn-primary:active { background: #083891; }              /* pressed (primary-70) */
.btn-primary:disabled { background: var(--color-neutral-300); color: var(--color-neutral-500); cursor: not-allowed; }
.btn-primary[aria-busy="true"] { color: transparent; position: relative; }
.btn-primary[aria-busy="true"]::after {
  content: ""; position: absolute; width: 18px; height: 18px; border-radius: 50%;
  border: 2px solid rgba(255,255,255,.4); border-top-color: #fff; animation: krds-spin .8s linear infinite;
}
@keyframes krds-spin { to { transform: rotate(360deg); } }

.btn-secondary { background: var(--color-primary-50); color: var(--color-primary-700); border-color: var(--color-primary-500); }  /* HC: fill primary-95 */
.btn-secondary:hover { background: var(--color-primary-100); }
.btn-secondary:active { background: var(--color-primary-200); }
.btn-secondary:disabled { background: var(--bg-subtle); border-color: var(--border-subtle); color: var(--text-disabled); }

.btn-ghost { background: transparent; color: var(--text-primary); border-color: var(--border-default); }  /* tertiary */
.btn-ghost:hover { background: var(--bg-subtle); }
.btn-ghost:active { background: var(--color-neutral-100); }
.btn-ghost:disabled { color: var(--text-disabled); border-color: var(--border-subtle); }

.btn-danger { background: #DE3412; color: #fff; }          /* danger-50 */
.btn-danger:hover { background: #BD2C0F; }                 /* danger-60 */
.btn-danger:active { background: #8A240F; }                /* danger-70 */
.btn-danger:disabled { background: var(--color-neutral-200); color: var(--text-disabled); }
.field-label { display: block; font: 700 17px/1.5 inherit; color: var(--text-primary); margin-bottom: 8px; }
.field-label .req { color: var(--color-point-500); }
.input {
  width: 100%; height: 56px; padding: 0 16px;
  font: 400 17px/1.5 inherit; color: var(--text-primary);
  background: var(--bg-base); border: 1px solid var(--border-default); border-radius: var(--radius-lg);
}
.input::placeholder { color: var(--text-tertiary); }
.input:focus { outline: 2px solid #000000; box-shadow: 0 0 0 4px var(--border-focus); border-color: var(--border-focus); }
.input[aria-invalid="true"] { border-color: #DE3412; background: var(--color-error-bg); }
.field-error { margin-top: 8px; font-size: 15px; color: var(--color-error-fg); }
.input:disabled { background: var(--color-neutral-100); color: var(--text-disabled); border-color: var(--border-subtle); }
.card { background: var(--bg-elevated); border: 1px solid var(--border-subtle); border-radius: var(--radius-xl); padding: 24px; }
.card-emphasis { background: var(--color-primary-50); border-color: var(--color-primary-100); }
.card-outlined { background: transparent; border: 1px solid var(--border-default); }
.card-link:hover { border-color: var(--color-primary-500); }
.card-link:hover .card-title { text-decoration: underline; text-underline-offset: 4px; }
.badge { display: inline-flex; align-items: center; height: 24px; padding: 0 8px; border-radius: var(--radius-sm); font: 700 13px/1 inherit; }
.badge-solid   { background: var(--color-primary-500); color: #fff; }
.badge-subtle  { background: var(--color-primary-50); color: var(--color-primary-600); }
.badge-outline { border: 1px solid var(--border-default); color: var(--text-secondary); }
.masthead { background: var(--color-secondary-50); min-height: 32px; display: flex; align-items: center; gap: 8px; padding: 0 24px; font-size: 15px; color: var(--text-primary); }
.gov-header { background: var(--bg-base); border-bottom: 1px solid var(--border-subtle); }
.gov-header__util { display: flex; justify-content: flex-end; gap: 16px; padding: 8px 24px 0; font-size: 13px; color: var(--text-secondary); }
.gov-header__main { display: flex; align-items: center; gap: 40px; height: 72px; padding: 0 24px; }
.gov-gnb a { font: 700 17px/1.5 inherit; color: var(--text-primary); text-decoration: none; padding: 24px 4px; border-bottom: 3px solid transparent; }
.gov-gnb a:hover { color: var(--color-primary-600); }
.gov-gnb a[aria-current="page"] { color: var(--color-primary-600); border-bottom-color: var(--color-primary-500); }
